import { ProfileContextConflict } from '../../storage/profiles/contextReceipts';
import { createReferenceOnboardingRoutes } from './referenceOnboarding';
import {
  callerAccount,
  createGuidanceRoutes,
  guidanceErrorStatus,
} from './guidance';
import { GuidanceError } from '../../types/guidance';
import type {
  TelemetryService,
  ProfileOperation,
} from '../../services/TelemetryService';
import { Router, type ErrorRequestHandler } from 'express';
import { z } from 'zod';
import {
  SourceFamilySchema,
  SourceRefreshRequestSchema,
  SourceSyncModeSchema,
} from '../../types/source-sync';
import {
  DesignReferenceRequestSchema,
  DesignReferenceSearchRequestSchema,
  type AgentReferenceSearchResult,
  type DesignLibrarySnapshot,
  type DesignReferenceSearchResult,
} from '../../types/design-library';
import type { ReferenceProfileStatusResponse } from '../../types/api-responses';
import type { DesignProfiles } from '../../services/profiles/DesignProfiles';
import {
  ProfilePreparationRequestSchema,
  ProfileContextSchema,
  ProfileRuntimeSchema,
  ProfileSettingsSchema,
  ProfileVariantInputSchema,
} from '../../types/design-profile';

const textInput = z
  .object({
    title: z.string().trim().min(1).max(500),
    text: z.string().trim().min(1).max(8000),
    runtime: ProfileRuntimeSchema,
    evidence: z.enum(['observation', 'preference']).default('observation'),
  })
  .strict();
const imageInput = z
  .object({
    title: z.string().trim().min(1).max(500),
    files: z.array(z.string().min(1).max(2048)).min(1).max(100),
    runtime: ProfileRuntimeSchema,
  })
  .strict();

const profileSettingOperation = (body: {
  isEnabled?: unknown;
  autonomousReferences?: unknown;
}): ProfileOperation['operation'] => {
  if (body?.isEnabled === undefined && body?.autonomousReferences !== undefined)
    return 'autonomy_setting';
  return body?.isEnabled ? 'enable' : 'disable';
};

export const createProfileRoutes = (
  profiles: DesignProfiles,
  telemetry?: TelemetryService,
): Router => {
  const router = Router();
  router.use(createGuidanceRoutes(profiles, telemetry));
  router.use(createReferenceOnboardingRoutes(profiles, telemetry));
  router.use((req, res, next) => {
    const started = Date.now();
    res.once('finish', () => {
      let operation: ProfileOperation['operation'] | undefined;
      const route = req.route?.path;
      if (req.method === 'POST' && route === '/profile/reference-contexts')
        operation = 'reference_lookup';
      if (req.method === 'POST' && route === '/profile/search')
        operation = 'reference_search';
      if (req.method === 'PATCH' && route === '/profile')
        operation = profileSettingOperation(req.body);
      if (req.method === 'POST' && route === '/profile/text')
        operation = 'text_import';
      if (req.method === 'POST' && route === '/profile/images')
        operation = 'image_import';
      if (req.method === 'POST' && route === '/profile/variants')
        operation = 'variant_import';
      if (req.method === 'POST' && route === '/profile/index-rebuilds')
        operation = 'index_rebuild';
      if (req.method === 'POST' && route === '/profile/sources')
        operation = 'source_connect';
      if (
        req.method === 'POST' &&
        (route === '/profile/sources/:id/refreshes' ||
          route === '/profile/source-sync/refreshes')
      )
        operation = 'source_refresh';
      if (req.method === 'PATCH' && route === '/profile/jobs/:id')
        operation = 'job_control';
      if (req.method === 'PATCH' && route === '/profile/sources/:id')
        operation = 'source_control';
      if (operation && !res.locals.isProfileOperationTracked)
        telemetry?.trackProfileOperation({
          stage: 'action',
          operation,
          outcome: res.statusCode < 400 ? 'completed' : 'failed',
          durationMs: Date.now() - started,
        });
    });
    next();
  });
  router.get('/profile', async (_req, res) => {
    res.json(
      (await profiles.status()) satisfies ReferenceProfileStatusResponse,
    );
  });
  router.get('/profile/diagnostics', async (_req, res) => {
    res.json(await profiles.diagnostics());
  });
  router.get('/profile/contexts/:id', async (req, res) => {
    const id = z.string().min(1).max(200).parse(req.params.id);
    const context = await profiles.inspect(id);
    if (!context) {
      res.status(404).json({
        error:
          'No recorded profile context for this request. It may be unavailable, still preparing, or belong to another account. Do not rerun suggestions to explain a past run.',
      });
      return;
    }
    res.json(context);
  });
  router.put('/profile/contexts/:id', async (req, res) => {
    const input = z
      .object({ profileId: z.string().min(1), context: ProfileContextSchema })
      .strict()
      .parse(req.body);
    if (input.context.requestId !== req.params.id) {
      res.status(400).json({
        error: 'Context receipt identity must match the request path',
      });
      return;
    }
    try {
      res.json(await profiles.recordContext(input));
    } catch (error) {
      if (!(error instanceof ProfileContextConflict)) throw error;
      res.status(409).json({ error: error.message });
    }
  });
  router.get('/profile/pins', async (req, res) => {
    res.json(
      await profiles.pins(
        z.string().min(1).max(200).optional().parse(req.query.projectId),
      ),
    );
  });
  router.post('/profile/variants', async (req, res) => {
    res
      .status(202)
      .json(
        await profiles.addVariant(ProfileVariantInputSchema.parse(req.body)),
      );
  });
  router.post('/profile/index-rebuilds', async (req, res) => {
    const input = z
      .object({ runtime: ProfileRuntimeSchema })
      .strict()
      .parse(req.body);
    res.status(202).json(await profiles.reindex(input.runtime));
  });
  router.patch('/profile', async (req, res) => {
    const input = ProfileSettingsSchema.parse(req.body);
    res
      .status(input.isEnabled ? 202 : 200)
      .json(
        (await profiles.updateSettings(
          input,
        )) satisfies ReferenceProfileStatusResponse,
      );
  });
  router.get('/profile/references', async (req, res) => {
    res.json({
      references: await profiles.references(
        z.string().optional().parse(req.query.sourceId),
      ),
    });
  });
  router.get('/profile/library', async (_req, res) => {
    res.setHeader('Cache-Control', 'private, no-store');
    res.json((await profiles.library()) satisfies DesignLibrarySnapshot);
  });
  router.post('/profile/search', async (req, res) => {
    res.setHeader('Cache-Control', 'private, no-store');
    const input = DesignReferenceSearchRequestSchema.parse(req.body);
    if (!input.isAgentSearch) {
      res.json(
        (await profiles.search(input)) satisfies DesignReferenceSearchResult,
      );
      return;
    }
    res.locals.isProfileOperationTracked = true;
    try {
      res.json(
        (await profiles.searchForAgent(
          input,
          callerAccount(req),
        )) satisfies AgentReferenceSearchResult,
      );
    } catch (error) {
      if (!(error instanceof ProfileContextConflict)) throw error;
      res.status(409).json({ error: error.message });
    }
  });
  router.post('/profile/reference-contexts', async (req, res) => {
    res.setHeader('Cache-Control', 'private, no-store');
    const input = DesignReferenceRequestSchema.parse(req.body);
    try {
      const context = await profiles.referenceContexts(input);
      if (!context) {
        res.status(404).json({
          error: 'Saved reference is unavailable in this account library.',
        });
        return;
      }
      res.json(context);
    } catch (error) {
      if (!(error instanceof ProfileContextConflict)) throw error;
      res.status(409).json({ error: error.message });
    }
  });
  router.get('/profile/references/:id/media/:hash', async (req, res) => {
    const media = await profiles.referenceMedia({
      profileId: z.string().uuid().parse(req.query.profileId),
      referenceId: z
        .string()
        .regex(/^[a-f0-9]{64}$/)
        .parse(req.params.id),
      hash: z
        .string()
        .regex(/^[a-f0-9]{64}$/)
        .parse(req.params.hash),
    });
    res.setHeader('Cache-Control', 'private, no-store');
    if (!media) {
      res.status(404).json({ error: 'Saved reference image is unavailable.' });
      return;
    }
    res.setHeader('X-Content-Type-Options', 'nosniff');
    res.type(media.mimeType).send(media.bytes);
  });
  router.post('/profile/text', async (req, res) => {
    res.status(201).json(await profiles.addText(textInput.parse(req.body)));
  });
  router.post('/profile/images', async (req, res) => {
    res.status(202).json(await profiles.addImages(imageInput.parse(req.body)));
  });
  router.post('/profile/sources', async (req, res) => {
    res
      .status(202)
      .json(
        await profiles.connect(
          z
            .object({ url: z.string().url(), runtime: ProfileRuntimeSchema })
            .strict()
            .parse(req.body),
        ),
      );
  });
  const sourceSync = Router();
  sourceSync.get('/profile/source-sync', async (req, res) => {
    const family = SourceFamilySchema.optional().parse(req.query.family);
    res.json({
      sources: await profiles.sourceSyncStates(family, callerAccount(req)),
    });
  });
  sourceSync.post('/profile/source-sync/refreshes', async (req, res) => {
    res.status(202).json({
      sources: await profiles.requestSourceRefresh(
        SourceRefreshRequestSchema.parse(req.body),
        callerAccount(req),
      ),
    });
  });
  const handleGuidanceError: ErrorRequestHandler = (error, _req, res, next) => {
    if (!(error instanceof GuidanceError)) {
      next(error);
      return;
    }
    res
      .status(guidanceErrorStatus[error.code])
      .json({ error: error.message, code: error.code });
  };
  sourceSync.use(handleGuidanceError);
  router.use(sourceSync);
  router.post('/profile/sources/:id/refreshes', async (req, res) => {
    res.status(202).json(
      await profiles.refresh({
        id: z.string().parse(req.params.id),
        runtime: ProfileRuntimeSchema.parse(req.body?.runtime),
      }),
    );
  });
  router.patch('/profile/jobs/:id', async (req, res) => {
    res.json(
      await profiles.updateJob({
        id: z.string().parse(req.params.id),
        action: z.enum(['pause', 'resume', 'retry']).parse(req.body?.action),
      }),
    );
  });
  router.patch('/profile/sources/:id', async (req, res) => {
    const input = z
      .object({
        isIncluded: z.boolean().optional(),
        isRemoved: z.boolean().optional(),
        syncMode: SourceSyncModeSchema.optional(),
        runtime: ProfileRuntimeSchema,
      })
      .strict()
      .parse(req.body);
    await profiles.updateSource({
      ...input,
      id: z.string().parse(req.params.id),
    });
    res.json(await profiles.status());
  });
  router.post('/profile/preparations', async (req, res) => {
    const accountId = z.string().min(1).parse(req.body?.accountId);
    const input = ProfilePreparationRequestSchema.parse(req.body);
    try {
      res.json(await profiles.prepare(input, accountId));
    } catch (error) {
      if (!(error instanceof ProfileContextConflict)) throw error;
      res.status(409).json({ error: error.message });
    }
  });
  return router;
};
